<?php use SwimlogStandalone\PersonalBestComparison as PC;use SwimlogStandalone\SwimComparison as SC;use SwimLogEvaluation\Workout;require_once __DIR__.'/SwimComparison.php';$valid=!is_wp_error($pbComparison); ?>
<section class="calendar-panel workout-page" aria-labelledby="pb-comparison-title"><h2 id="pb-comparison-title">Compare Personal Bests</h2>
<p>Compare your fastest eligible pool-swim performances within two periods. Each result comes from the plugin’s evaluated performances, including results that are not current lifetime PBs. Meters and yards remain separate.</p>
<?php if(!$valid): ?><p role="alert"><?php echo esc_html($pbComparison->get_error_message()); ?></p><?php endif; ?>
<form method="get" action="/" class="pb-comparison-filters"><input type="hidden" name="screen" value="compare_bests"><label>Course <select name="course"><?php foreach(array('m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected(is_string($_GET['course']??null)?$_GET['course']:'m',$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label>
<div class="comparison-summaries"><?php foreach(array('a','b')as$i=>$prefix):$v=$valid?$pbComparison['periods'][$i]['values']:array('mode'=>'year','year'=>(string)((int)wp_date('Y')-($i===0?1:0)),'month'=>wp_date('Y-m'),'from'=>wp_date('Y-01-01'),'to'=>wp_date('Y-m-d'),'min_age'=>$i===0?'55':'60','max_age'=>$i===0?'59':'64');foreach($v as$key=>$unused)if(is_string($_GET[$prefix.'_'.$key]??null))$v[$key]=$_GET[$prefix.'_'.$key]; ?>
<fieldset data-pb-period><legend><?php echo $i===0?'Group A':'Group B'; ?></legend><label>Period type <select name="<?php echo esc_attr($prefix); ?>_mode" data-period-mode><?php foreach(array('year'=>'Calendar year','month'=>'Calendar month','dates'=>'Custom dates','age'=>'Age range')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($v['mode'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label>
<?php foreach(array('year'=>array('year'=>array('Year','number')),'month'=>array('month'=>array('Month','month')),'dates'=>array('from'=>array('From (inclusive)','date'),'to'=>array('To (inclusive)','date')),'age'=>array('min_age'=>array('Youngest age (inclusive)','number'),'max_age'=>array('Oldest age (inclusive)','number')))as$mode=>$fields): ?><div data-period-fields="<?php echo esc_attr($mode); ?>"><?php foreach($fields as$key=>$field): ?><label><?php echo esc_html($field[0]); ?><input name="<?php echo esc_attr($prefix.'_'.$key); ?>" type="<?php echo esc_attr($field[1]); ?>" value="<?php echo esc_attr($v[$key]); ?>" <?php if($key==='year')echo 'min="1900" max="2199"';elseif($mode==='age')echo 'min="0" max="150"'; ?>></label><?php endforeach; ?></div><?php endforeach; ?></fieldset><?php endforeach; ?></div>
<p>Ages are calculated on each swim’s local date using your configured birth date. Dates are inclusive in the WordPress site timezone; future workouts are excluded. <a href="/?screen=swimmer">Swimmer Configuration</a></p><button>Compare Personal Bests</button></form><script src="/assets/pb-comparison.js" defer></script>
<?php if($valid):$m=$pbComparison; ?><h3><?php echo esc_html('A: '.$m['periods'][0]['label'].' · B: '.$m['periods'][1]['label']); ?></h3><p>A positive B − A time means B was slower; a negative time means B was faster. Charts compare exact matching stroke, distance and course only. Missing results stay missing.</p>
<?php if($m['overlap']): ?><p>The calendar spans overlap. A swim can appear in both groups when it meets both filters; age ranges are applied independently.</p><?php endif; ?>
<?php if(!$m['rows']): ?><p role="status">No eligible performances were recorded for these periods and course.</p><?php endif; ?>
<?php foreach($m['rows']as$row):$a=$row['a'];$b=$row['b'];$event=$a?:$b; ?><section class="comparison-stroke"><h3><?php echo esc_html($event['distance'].' '.$m['course'].' · '.array('FR'=>'Freestyle','BR'=>'Breaststroke','BACK'=>'Backstroke','FLY'=>'Butterfly','MIXED'=>'Mixed')[$event['stroke']]); ?></h3>
<div class="comparison-summaries"><?php foreach(array($a,$b)as$i=>$r): ?><section><h4><?php echo $i===0?'Group A':'Group B'; ?></h4><?php if(!$r): ?><p>No eligible result</p><?php else: ?><p><?php echo esc_html(Workout::format_duration($r['ms']).' · '.$r['date']); ?></p><a class="control" data-workout-id="<?php echo esc_attr($r['workout_id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url('/?workout='.$r['workout_id']); ?>">View supporting swim <?php echo $i===0?'A':'B'; ?></a><?php endif; ?></section><?php endforeach; ?></div>
<?php if($a&&$b):$d=$b['ms']-$a['ms']; ?><p><?php echo esc_html('Time change: '.SC::delta($a['ms'],$b['ms'],'avg_pace_100_ms',true).' · '.($d>0?'+':'').number_format_i18n(100*$d/$a['ms'],2).'%'); ?></p><?php echo SC::chart($a['ms'],$b['ms'],'avg_pace_100_ms',$event['distance'].' '.$m['course'].' '.$event['stroke'].' · performance times; A blue, B brown');else: ?><p>Time change and paired chart unavailable without a result in both groups.</p><?php endif; ?></section><?php endforeach;endif; ?></section>
